; image_table.asm, 0BFE00-0C0000: the image pointer table, then zero to the end of pair W.
; Owner: the images leg (M5i, docs/15-gsp-images.md). Source: data/gsp-images.
;
; 0BFE00-0BFF18: 70 longs, generated by tools/gspimages asm (../../build/gsp-images/table.asm):
; entry 0 = 0, entries 1-57 and 65-68 the labels of their streams (entries that share a stream
; point at the same label), 58-64 placeholders pointing at gsp_images_sum_u, the pair-U adjust
; word at 060000, and entry 69 = 0 (yet 02DB54 unpacks it: docs/15 section 5). Indexed from its
; base by lea $bfe00 at 022798 and addi.l #$bfe00 at 024AC4 and eight more places (docs/06
; section 4.2).

	assert	*=$0BFE00,"image_table.asm misplaced"

tbl_BFE00:
	include	"../../build/gsp-images/table.asm"

; 0BFF18-0C0000: zero (232 bytes)
	dcb.b	$0C0000-*,0

	assert	*=$0C0000,"image_table.asm does not end at 0C0000"
